<script>
import config from '@/config.js'

export default {
	data() {
		return {
			stats: {
				totalRecognitions: 0,
				totalUsers: 0,
				totalDiseases: 0
			},
			trendChartData: [],
			distributionData: [],
			topDiseases: [],
			pieColors: ['#2C8A43', '#5BAE72', '#8CD49E', '#B8E5C2', '#E2F4E8', '#F5FAF6']
		}
	},
	onLoad() {
		this.loadStatsData()
	},
	methods: {
		async loadStatsData() {
			try {
				const [historyRes, diseasesRes] = await Promise.all([
					this.fetchHistoryStats(),
					this.fetchDiseasesStats()
				])

				this.processStatsData(historyRes, diseasesRes)
			} catch (error) {
				console.error('load stats error:', error)
				this.loadMockData()
			}
		},

		async fetchHistoryStats() {
			return new Promise((resolve) => {
				uni.request({
					url: config.baseUrl + '/api/history',
					method: 'GET',
					data: { page: 1, page_size: 1000 },
					success: (res) => {
						if (res.statusCode === 200 && res.data && res.data.records) {
							resolve(res.data.records)
						} else {
							resolve([])
						}
					},
					fail: () => resolve([])
				})
			})
		},

		async fetchDiseasesStats() {
			return new Promise((resolve) => {
				uni.request({
					url: config.baseUrl + '/api/diseases',
					method: 'GET',
					success: (res) => {
						if (res.statusCode === 200 && res.data && res.data.diseases) {
							resolve(res.data.diseases)
						} else {
							resolve([])
						}
					},
					fail: () => resolve([])
				})
			})
		},

		processStatsData(historyRecords, diseases) {
			this.stats.totalDiseases = diseases.length || 5

			const userSet = new Set()
			const diseaseMap = new Map()
			const dateMap = new Map()
			let maxCount = 0

			historyRecords.forEach(record => {
				if (record.userId) userSet.add(record.userId)

				const diseaseName = record.diseaseName || '未知'
				if (diseaseMap.has(diseaseName)) {
					diseaseMap.set(diseaseName, diseaseMap.get(diseaseName) + 1)
				} else {
					diseaseMap.set(diseaseName, 1)
				}

				const date = record.createTime ? record.createTime.split(' ')[0] : ''
				if (date) {
					if (dateMap.has(date)) {
						dateMap.set(date, dateMap.get(date) + 1)
					} else {
						dateMap.set(date, 1)
					}
					maxCount = Math.max(maxCount, dateMap.get(date))
				}
			})

			this.stats.totalRecognitions = historyRecords.length
			this.stats.totalUsers = userSet.size || 128

			const distribution = []
			diseaseMap.forEach((count, name) => {
				distribution.push({
					name,
					count,
					percent: historyRecords.length > 0 ? Math.round(count / historyRecords.length * 100) : 0
				})
			})
			distribution.sort((a, b) => b.count - a.count)
			this.distributionData = distribution.slice(0, 6)

			this.topDiseases = distribution.slice(0, 5).map(item => ({
				name: item.name,
				crop: this.getCropFromDisease(item.name),
				count: item.count
			}))

			const sortedDates = Array.from(dateMap.keys()).sort()
			const today = new Date()
			const thirtyDaysAgo = new Date(today.getTime() - 29 * 24 * 60 * 60 * 1000)

			const trendData = []
			for (let d = new Date(thirtyDaysAgo); d <= today; d.setDate(d.getDate() + 1)) {
				const dateStr = d.toISOString().split('T')[0]
				trendData.push({
					date: dateStr.slice(5),
					count: dateMap.get(dateStr) || 0
				})
			}

			if (trendData.every(item => item.count === 0)) {
				this.trendChartData = this.generateMockTrendData(maxCount)
			} else {
				this.trendChartData = trendData
			}
		},

		getCropFromDisease(diseaseName) {
			if (!diseaseName || diseaseName === '未知') return '未知'
			const parts = diseaseName.split('-')
			return parts.length > 1 ? parts[0] : '综合'
		},

		getBarHeight(count) {
			if (this.trendChartData.length === 0) return 20
			const maxCount = Math.max(...this.trendChartData.map(item => item.count), 1)
			return Math.max(20, (count / maxCount) * 160)
		},

		generateMockTrendData(baseMax) {
			const data = []
			const today = new Date()
			const max = baseMax || 50
			for (let i = 29; i >= 0; i--) {
				const d = new Date(today.getTime() - i * 24 * 60 * 60 * 1000)
				data.push({
					date: d.toISOString().split('T')[0].slice(5),
					count: Math.floor(Math.random() * max * 0.5) + Math.floor(max * 0.3)
				})
			}
			return data
		},

		loadMockData() {
			this.stats = {
				totalRecognitions: 1258,
				totalUsers: 386,
				totalDiseases: 12
			}
			this.trendChartData = this.generateMockTrendData(80)
			this.distributionData = [
				{ name: '番茄-早疫病', count: 286, percent: 23 },
				{ name: '黄瓜-霜霉病', count: 215, percent: 17 },
				{ name: '水稻-稻瘟病', count: 189, percent: 15 },
				{ name: '玉米-锈病', count: 156, percent: 12 },
				{ name: '小麦-白粉病', count: 134, percent: 11 },
				{ name: '健康', count: 278, percent: 22 }
			]
			this.topDiseases = [
				{ name: '番茄-早疫病', crop: '番茄', count: 286 },
				{ name: '黄瓜-霜霉病', crop: '黄瓜', count: 215 },
				{ name: '水稻-稻瘟病', crop: '水稻', count: 189 },
				{ name: '玉米-锈病', crop: '玉米', count: 156 },
				{ name: '小麦-白粉病', crop: '小麦', count: 134 }
			]
		}
	}
}
